installer-gui-script.script:
function checkOBS() {
  var info = system.files.plistAtPath('/Applications/OBS.app/Contents/Info.plist');
  if (info && info.CFBundleShortVersionString === '32.2.2') return true;
  my.result.type = 'Fatal';
  my.result.title = 'Interpretwitch';
  my.result.message = system.localizedString('OBSRequired');
  return false;
}
